import {ANIMALS,FARM_POINTS,dailyStatus} from './farm.mjs';
export function farmClearance(x,z){return Object.values(ANIMALS).filter(a=>a.id!=='jonny').some(a=>Math.hypot(x-a.x,z-a.z)<4)||Math.abs(x-HOF.coop.x)<3&&Math.abs(z-HOF.coop.z)<3||Math.hypot(x-HOF.well.x,z-HOF.well.z)<2;}
export function createFarmWorld(scene,height,colliders,interactive,animated,horse,materials,player){
 let housingKit=null;const animals=new Map(),clickTargets=[],eggMeshes=[],waterMeshes=[],feedMeshes=[];
 const mat=(color,extra={})=>new T.MeshStandardMaterial({color,roughness:.9,...extra});
 const brown=mat('#9a8062'),cream=mat('#ede5cf'),dark=mat('#41463d'),pink=mat('#c8a397'),metal=mat('#a68b55',{metalness:.5,roughness:.5}),wood=materials.wood,hay=mat('#b9aa69'),water=mat('#83aaa8',{roughness:.2,metalness:.18});
 function mesh(g,m,p=scene){const o=new T.Mesh(g,m);o.castShadow=true;o.receiveShadow=true;p.add(o);return o;}
 function box(w,h,d,m,x,y,z,p=scene){const o=mesh(new T.BoxGeometry(w,h,d),m,p);o.position.set(x,y,z);return o;}
 function ball(m,x,y,z,sx,sy,sz,p){const o=mesh(new T.SphereGeometry(1,20,14),m,p);o.position.set(x,y,z);o.scale.set(sx,sy,sz);return o;}
 function rod(a,b,r,m,p){const u=new T.Vector3(...a),v=new T.Vector3(...b),delta=v.clone().sub(u),o=mesh(new T.CylinderGeometry(r,r,delta.length(),8),m,p);o.position.copy(u.add(v).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.normalize());return o;}
 function cowCoat(base,patch,seed){const scan=generatedMap('animal-materials',0);if(scan)return mat('#ffffff',{map:scan,roughness:.96,bumpMap:scan,bumpScale:.004});const c=document.createElement('canvas');c.width=512;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle=base;ctx.fillRect(0,0,512,256);let v=seed;const rnd=()=>{v=(Math.imul(v,1664525)+1013904223)>>>0;return v/4294967296;};ctx.fillStyle=patch;for(let n=0;n<7;n++){const x=rnd()*512,y=45+rnd()*175,r=25+rnd()*38;ctx.beginPath();for(let j=0;j<=30;j++){const a=j/30*Math.PI*2,rr=r*(.8+.16*Math.sin(a*3+n)+.12*Math.cos(a*5));const px=x+Math.cos(a)*rr,py=y+Math.sin(a)*rr*.8;if(j===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);}ctx.fill();}for(let i=0;i<3800;i++){const x=rnd()*512,y=rnd()*256;ctx.strokeStyle='rgba(79,57,36,.045)';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+1,y+2);ctx.stroke();}const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;return mat('#ffffff',{map:tex});}
 function cow(id){
  const def=ANIMALS[id],g=new T.Group(),coat=cowCoat(id==='berta'?'#907052':'#e9e1cc',id==='berta'?'#e9dfc4':'#6b5644',id==='berta'?182:431);scene.add(g);g.position.set(def.x,height(def.x,def.z),def.z);g.userData.kind='farm-cow';
  ball(coat,0,1.18,0,.55,.58,1.05,g);ball(coat,0,1.12,-.8,.51,.47,.49,g);ball(coat,0,1.28,.65,.4,.48,.44,g);
  const head=new T.Group();head.position.set(0,1.45,.95);g.add(head);ball(coat,0,.01,.18,.23,.32,.34,head);ball(pink,0,-.2,.48,.245,.14,.22,head);
  for(const side of[-1,1]){ball(coat,side*.39,.19,.07,.22,.065,.13,head);ball(pink,side*.4,.2,.1,.13,.025,.08,head);ball(dark,side*.242,.09,.31,.037,.029,.026,head);ball(cream,side*.254,.105,.33,.01,.01,.007,head);ball(dark,side*.15,-.18,.7,.045,.025,.015,head);const horn=mesh(new T.ConeGeometry(.06,.31,12),cream,head);horn.position.set(side*.2,.46,.02);horn.rotation.z=-side*.3;}
  const legs=[];for(const x of[-.34,.34])for(const z of[-.65,.65]){const leg=new T.Group();leg.position.set(x,.92,z);g.add(leg);const upper=mesh(new T.CapsuleGeometry(.095,.35,5,12),coat,leg);upper.position.y=-.24;const lower=mesh(new T.CapsuleGeometry(.065,.27,5,12),coat,leg);lower.position.set(0,-.65,0);ball(dark,0,-.86,.05,.11,.09,.14,leg);legs.push(leg);}
  const udder=ball(pink,0,.65,-.45,.25,.16,.27,g);for(const x of[-.11,.11])for(const z of[-.55,-.35])rod([x,.62,z],[x,.44,z],.027,pink,g);
  const tail=new T.Group();tail.position.set(0,1.4,-1);g.add(tail);rod([0,0,0],[0,-.62,-.1],.035,coat,tail);ball(dark,0,-.72,-.1,.07,.18,.07,tail);
  const collar=mesh(new T.TorusGeometry(.34,.035,8,24),dark,g);collar.position.set(0,1.3,.78);collar.rotation.x=.5;const bell=mesh(new T.CylinderGeometry(.1,.16,.24,16),metal,g);bell.position.set(0,.95,.95);
  g.traverse(o=>{if(o.isMesh)o.userData.farmAnimal=id;});clickTargets.push(g);
  const collider={type:'circle',x:def.x,z:def.z,r:.78};colliders.push(collider);const point={id:'animal-'+id,name:def.name+' versorgen',x:def.x+1.7,z:def.z+1,range:2.3,animal:id};interactive.push(point);
  animated.push(t=>{if(housingKit?.owns(id))return;const offset=id==='berta'?0:2.7,a=t*.12+offset;let x=def.x+Math.sin(a)*.65,z=def.z+Math.cos(a*.8)*.28,walking=Math.abs(Math.cos(a))>.6;if(player?.g.visible&&Math.hypot(x-player.g.position.x,z-player.g.position.z)<1.6){x=g.position.x;z=g.position.z;walking=false;}g.position.set(x,height(x,z),z);g.rotation.y=walking?(Math.cos(a)>0?1.4:-1.4):.2;head.rotation.x=walking?.05:.38+Math.sin(t*.6)*.04;tail.rotation.z=Math.sin(t*1.6+offset)*.2;legs.forEach((l,i)=>l.rotation.x=walking?Math.sin(t*3+i*Math.PI)*.16:0);collider.x=x;collider.z=z;point.x=x+1.7;point.z=z+1;});
  animals.set(id,{g,point,collider,legs});
 }
 cow('berta');cow('lotti');
 const goats=new T.Group();scene.add(goats);goats.userData.kind='farm-goats';
 for(let i=0;i<2;i++){const g=new T.Group(),coat=i?brown:cream;goats.add(g);ball(coat,0,.78,0,.24,.31,.55,g);const head=new T.Group();head.position.set(0,1.07,.5);g.add(head);ball(coat,0,0,.08,.15,.2,.2,head);ball(dark,0,-.08,.27,.1,.07,.08,head);for(const side of[-1,1]){ball(dark,side*.14,.06,.15,.022,.025,.02,head);ball(coat,side*.2,.08,0,.13,.035,.06,head);rod([side*.08,.14,-.03],[side*.13,.46,-.2],.025,cream,head);}rod([0,-.12,.17],[0,-.32,.1],.025,coat,head);const legs=[];for(const x of[-.18,.18])for(const z of[-.33,.33]){const l=rod([x,.65,z],[x,.08,z],.04,coat,g);legs.push(l);ball(dark,x,.07,z,.055,.06,.075,g);}animated.push(t=>{if(housingKit?.owns('goats'))return;const x=ANIMALS.goats.x+Math.sin(t*.15+i*2)*.7,z=ANIMALS.goats.z+Math.cos(t*.1+i)*.5;g.position.set(x,height(x,z),z);g.rotation.y=Math.sin(t*.15+i)*.25;head.rotation.x=.12+Math.sin(t*.6+i)*.18;legs.forEach((l,k)=>l.rotation.x=Math.sin(t*2+i+k)*.04);});}
 goats.traverse(o=>{if(o.isMesh)o.userData.farmAnimal='goats';});clickTargets.push(goats);const gp={id:'animal-goats',name:'Maja und Sämi versorgen',x:ANIMALS.goats.x+1.6,z:ANIMALS.goats.z+1,range:2.4,animal:'goats'};interactive.push(gp);animals.set('goats',{g:goats,point:gp});colliders.push({type:'circle',x:ANIMALS.goats.x,z:ANIMALS.goats.z,r:1});

 const hens=new T.Group();scene.add(hens);hens.userData.kind='farm-hens';
 for(let i=0;i<3;i++){const def=ANIMALS.hens,g=new T.Group(),coat=[cream,brown,dark][i];hens.add(g);g.userData.kind='visible-alpine-hen';g.position.set(18.1+Math.cos(i*2.1)*1.15,height(18.1,1),1+Math.sin(i*2.1)*1.5);ball(coat,0,.4,0,.22,.27,.34,g);ball(coat,0,.68,.23,.13,.16,.14,g);for(const side of[-1,1])ball(dark,side*.12,.72,.29,.023,.024,.02,g);const beak=mesh(new T.ConeGeometry(.045,.13,8),hay,g);beak.rotation.x=Math.PI/2;beak.position.set(0,.66,.4);for(let j=0;j<3;j++)ball(pink,0,.86+j*.01,.12+j*.08,.04,.075,.05,g);for(const side of[-1,1]){ball(coat,side*.19,.45,-.02,.075,.18,.25,g);rod([side*.1,.25,.02],[side*.1,.055,.02],.018,metal,g);for(let j=-1;j<=1;j++)rod([side*.1,.05,.02],[side*.1+j*.04,.025,.16],.013,metal,g);}const tail=ball(coat,0,.5,-.32,.1,.2,.15,g);tail.rotation.x=-.5;
  animated.push(t=>{if(housingKit?.owns('hens'))return;const a=t*.24+i*2.1,x=18.1+Math.cos(a)*1.15,z=1+Math.sin(a*.8)*1.5;g.position.set(x,height(x,z),z);g.rotation.y=-a;g.rotation.x=Math.sin(t*3+i)*.025;});
 }
 hens.traverse(o=>{if(o.isMesh)o.userData.farmAnimal='hens';});clickTargets.push(hens);const hp={id:'animal-hens',name:'Hühner versorgen & Eier sammeln',x:ANIMALS.hens.x,z:ANIMALS.hens.z,range:2.8,animal:'hens'};interactive.push(hp);animals.set('hens',{g:hens,point:hp});
 const coop=new T.Group();coop.position.set(HOF.coop.x,height(HOF.coop.x,HOF.coop.z),HOF.coop.z);coop.rotation.y=-Math.PI/2;coop.userData.kind='hof-facing-henhouse';scene.add(coop);box(4,.5,3.1,wood,0,.25,0,coop);box(3.8,1.9,2.8,cream,0,1.4,0,coop);for(const side of[-1,1]){const roof=box(2.5,.14,3.6,wood,side*1.05,2.7,0,coop);roof.rotation.z=-side*.42;}box(.8,1,.1,dark,0,1,-1.45,coop);const ramp=box(.8,.1,2.2,wood,0,.45,-2,coop);ramp.rotation.x=-.35;colliders.push({...HOF.coop});
 for(let i=0;i<3;i++){const nest=new T.Group();nest.position.set(-1.2+i*1.2,.62,-1.9);coop.add(nest);const ring=mesh(new T.TorusGeometry(.32,.065,7,20),hay,nest);ring.rotation.x=Math.PI/2;const egg=ball(cream,0,.08,0,.09,.13,.09,nest);eggMeshes.push(egg);}

 // Existing Jonny is reused, preserving his course model and animation.
 horse.g.traverse(o=>{if(o.isMesh)o.userData.farmAnimal='jonny';});clickTargets.push(horse.g);animals.set('jonny',{g:horse.g,legs:horse.legs,point:{x:6,z:3}});
 // Daily supplies are collected at the main barn, without a second scattered shelter.
 interactive.push({id:'farm-barn',...FARM_POINTS.barn,name:'Leiheimer in der Scheune holen',farmSupply:'barn',range:2.2});
 // A hollow timber trough instead of a solid stone cylinder, within its old collision radius.
 const troughMap=generatedMap('trough-material'),troughWood=mat(troughMap?'#ffffff':'#806748',{map:troughMap,bumpMap:troughMap,bumpScale:.014});const well=new T.Group();well.userData.kind='timber-alp-trough';well.position.set(-11.6,height(-11.6,1),1);scene.add(well);
 for(const x of[-.58,.58])box(.2,.2,.74,materials.stone,x,.1,0,well);
 box(1.72,.12,.84,troughWood,0,.24,0,well);
 for(const side of[-1,1]){box(1.72,.4,.14,troughWood,0,.48,side*.38,well);box(.14,.4,.64,troughWood,side*.79,.48,0,well);}
 for(const x of[-.55,.55]){for(const side of[-1,1])box(.035,.41,.018,dark,x,.48,side*.459,well);box(.035,.02,.9,dark,x,.69,0,well);}
 const surface=mesh(new T.PlaneGeometry(1.4,.59),water,well);surface.rotation.x=-Math.PI/2;surface.position.y=.57;
 rod([-.65,.3,-.15],[-.65,1.5,-.15],.085,wood,well);rod([-.65,1.25,-.15],[-.15,1.25,-.15],.035,metal,well);const jetCurve=new T.CatmullRomCurve3([new T.Vector3(-.15,1.25,-.15),new T.Vector3(.02,1.2,-.15),new T.Vector3(.13,.95,-.15),new T.Vector3(.17,.58,-.15)]),jet=mesh(new T.TubeGeometry(jetCurve,20,.025,8,false),new T.MeshStandardMaterial({color:'#d4f3ed',transparent:true,opacity:.72,roughness:.12,depthWrite:false}),well);jet.userData.kind='fountain-water-jet';jet.userData.outlet=[-.15,1.25,-.15];jet.userData.impact=[.17,.58,-.15];
 const ripple=mesh(new T.RingGeometry(.075,.09,32),new T.MeshBasicMaterial({color:'#e4f6eb',transparent:true,opacity:.6,side:T.DoubleSide,depthWrite:false}),well);ripple.rotation.x=-Math.PI/2;ripple.position.set(.17,.578,-.15);const drops=new T.InstancedMesh(new T.SphereGeometry(.014,6,5),jet.material,12),dropPose=new T.Object3D();well.add(drops);animated.push(t=>{ripple.scale.setScalar(.5+(t*1.25%1)*1.6);ripple.material.opacity=.55*(1-t*1.25%1);for(let i=0;i<12;i++){const phase=(t*1.8+i/12)%1,a=i*2.4;dropPose.position.set(.17+Math.cos(a)*phase*.1,.58+Math.sin(phase*Math.PI)*.09,-.15+Math.sin(a)*phase*.1);dropPose.updateMatrix();drops.setMatrixAt(i,dropPose.matrix);}drops.instanceMatrix.needsUpdate=true;});
 for(let i=0;i<9;i++){const a=i*2.4,r=.8+(i%3)*.08,o=mesh(new T.IcosahedronGeometry(1,1),materials.stone,well);o.position.set(Math.cos(a)*r,.05,Math.sin(a)*r*.65);o.scale.set(.12,.06,.1);}const moss=mat('#667c43');for(let i=0;i<6;i++)ball(moss,-.75+i*.29,.31,.46,.12,.025,.04,well);colliders.push({type:'circle',x:-11.6,z:1,r:.95});interactive.push({id:'farm-well',...FARM_POINTS.well,name:'Am Alpbrunnen Wasser holen',farmSupply:'well',range:2.1});
 for(const def of Object.values(ANIMALS)){const x=def.x+(def.id==='hens'?1.4:1.6),z=def.z-1.7,g=new T.Group();g.position.set(x,height(x,z),z);scene.add(g);colliders.push({x:x+.35,z,w:2,d:1.1});for(const side of[-1,1])box(.1,.4,1,wood,side*.55,.2,0,g);box(1.2,.1,1,wood,0,.1,0,g);const f=ball(hay,0,.23,0,.45,.08,.35,g);feedMeshes.push({id:def.id,m:f});const bowl=mesh(new T.CylinderGeometry(.28,.24,.15,18),metal,g);bowl.position.set(1,.15,0);const ws=mesh(new T.CircleGeometry(.23,24),water,g);ws.rotation.x=-Math.PI/2;ws.position.set(1,.23,0);waterMeshes.push({id:def.id,m:ws});}
 housingKit=createFarmHousing(animals,colliders,height,horse,interactive);animated.push(t=>housingKit.step(t));
 return{animals,clickTargets,housingKit,well,sync(state){housingKit.sync(state);for(const f of feedMeshes)f.m.visible=dailyStatus(state,f.id).fed;for(const w of waterMeshes)w.m.visible=dailyStatus(state,w.id).watered;const h=dailyStatus(state,'hens');eggMeshes.forEach(m=>m.visible=h.fed&&h.watered&&h.cared&&!h.collected);}};
}
